// DOBRZE: 1 centralny filtr dla WSZYSTKICH endpointow naraz
Filter securityHeadersFilter = new Filter() {
    public void doFilter(HttpExchange exchange, Chain chain) throws IOException {
        exchange.getResponseHeaders().add("X-Frame-Options", "DENY");
        exchange.getResponseHeaders().add("Content-Security-Policy", "default-src 'self'");
        exchange.getResponseHeaders().add("X-Content-Type-Options", "nosniff");
        chain.doFilter(exchange); // KAZDY endpoint dostaje te naglowki AUTOMATYCZNIE
    }
    public String description() { return "Dodaje standardowe naglowki bezpieczenstwa"; }
};
server.createContext("/", handler).getFilters().add(securityHeadersFilter);
